<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\ClientMigrationAudit; use App\Services\ClientMigrationMatcher; use Illuminate\Http\Request; use PhpOffice\PhpSpreadsheet\IOFactory;
class ClientMigrationController extends Controller {
 public function preview(Request $request, ClientMigrationMatcher $matcher) { $request->validate(['file'=>'required|file|mimes:xlsx,xls,csv|max:10240']); $file=$request->file('file'); $rows=IOFactory::load($file->getRealPath())->getActiveSheet()->toArray(null,true,true,false); $headers=array_map('trim',array_shift($rows)??[]); $required=['Name','Address','Installation Date','Due Date','Previous balance','Current balance','Leases','Promo rates (Mbps)']; if($headers!==$required) return response()->json(['message'=>'Invalid headers. Download and use the migration template.'],422); $preview=[]; foreach($rows as $i=>$row){if(!array_filter($row,fn($v)=>$v!==null&&$v!==''))continue; $data=array_combine($headers,array_pad($row,count($headers),null)); $match=$matcher->find((string)$data['Leases']); $preview[]=['row'=>$i+2,'record'=>$data,'match_status'=>$match['status'],'lease_id'=>$match['lease']?->id,'candidate_lease_ids'=>$match['candidates']->pluck('id'),'requires_confirmation'=>$match['requires_confirmation']??false];} $audit=ClientMigrationAudit::create(['user_id'=>$request->user()->id,'filename'=>$file->getClientOriginalName(),'total_rows'=>count($preview),'preview'=>$preview,'summary'=>['preview_only'=>true]]); return response()->json(['audit_id'=>$audit->id,'rows'=>$preview]); }
}
